  "이미지·테두리 도형 등 선택한 객체의 모서리를 한 번에 맞춥니다.": ["一次性统一调整所选形状、图像和带边框对象等的边角样式。","画像や枠線付き図形など、選択したオブジェクトの角のスタイルをまとめて調整します。","Harmonisez en une fois le style des angles des formes, images et objets avec bordure sélectionnés."],
  "추론 수준": ["推理强度","推論レベル","Niveau de raisonnement"],
  "최대": ["最高","最高","Maximum"],
  "응답 토큰": ["响应令牌数","応答トークン","Jetons de réponse"],
  "최대 작업 단계": ["最大步骤数","最大ステップ数","Nombre maximal d’étapes"],
  "공동 목표": ["共同目标","共通の目標","Objectif commun"],
  "라우팅 판단 중": ["正在路由","ルーティング中","Routage en cours"],
  "{count}개 객체를 잘라냈습니다.": ["已剪切 {count} 个对象。","{count} 個のオブジェクトを切り取りました。","{count} objet(s) coupé(s)."],
  "브라우저 내부 클립보드를 사용합니다. 붙여넣기 버튼을 눌러주세요.": ["正在使用浏览器内部剪贴板。请点击粘贴按钮。","ブラウザーの内部クリップボードを使用しています。貼り付けボタンを押してください。","Utilisation du presse-papiers interne du navigateur. Cliquez sur Coller pour insérer."],
  "{count}개 객체를 복사했습니다.": ["已复制 {count} 个对象。","{count} 個のオブジェクトをコピーしました。","{count} objet(s) copié(s)."],
  "전송": ["发送","送信","Envoyer"],
  "사전 빌드 모드에서 결과물을 준비합니다.": ["正在预构建模式下准备输出。","事前ビルドモードで出力を準備しています。","Préparation du rendu en mode précompilé."],
  "사전 빌드": ["预构建","事前ビルド","Précompilation"],
  "HTML 미리보기": ["HTML 预览","HTML プレビュー","Aperçu HTML"],
  "새로고침": ["刷新","更新","Actualiser"],
  "최신 커밋부터 표시합니다. 색상 경로로 분기와 병합을 확인할 수 있습니다.": ["从最新提交开始显示。可通过彩色路径查看分支与合并。","最新のコミットから表示します。色の付いた経路で分岐とマージを確認できます。","Affichage à partir du commit le plus récent. Les tracés colorés indiquent les branches et les fusions."],
  "출력 일부가 생략되었습니다.": ["部分输出已省略。","出力の一部が省略されました。","Une partie de la sortie a été tronquée."],
  "셀 언어": ["单元格语言","セルの言語","Langage de la cellule"],
  "프로젝트 편집": ["编辑项目","プロジェクトを編集","Modifier le projet"],
  "작업을 여기에 놓으세요.": ["将任务拖放到这里。","タスクをここにドロップしてください。","Déposez les tâches ici."],
  "프로젝트 삭제": ["删除项目","プロジェクトを削除","Supprimer le projet"],
  "프로젝트와 포함된 모든 작업을 삭제할까요?": ["确定要删除此项目及其包含的所有任务吗？","このプロジェクトと含まれるすべてのタスクを削除しますか？","Supprimer ce projet et toutes les tâches qu’il contient ?"],
  "검색 결과가 없습니다.": ["没有搜索结果。","検索結果がありません。","Aucun résultat de recherche."],
