  "실행 환경 초기화": ["重置运行环境","実行環境をリセット","Réinitialiser l’environnement d’exécution"],
  "변수와 함수를 초기화했습니다. 파일은 유지됩니다.": ["已重置变量和函数，文件将保留。","変数と関数をリセットしました。ファイルは保持されます。","Les variables et fonctions ont été réinitialisées. Les fichiers sont conservés."],
  "연결 종료": ["断开连接","切断","Déconnecter"],
  "데이터 시트를 표 {count}개로 가져왔습니다. 첫 행은 열 이름으로 사용합니다.": ["已将数据表导入为 {count} 个表格。第一行将用作列标题。","データシートを {count} 個の表としてインポートしました。1 行目は列名として使用されます。","Feuille de données importée dans {count} tableau(x). La première ligne sert d’en-têtes de colonnes."],
  "프로젝트 생성은 캔버스 관리자만 가능합니다.": ["只有画布管理员可以创建项目。","プロジェクトの作成はキャンバス管理者のみ行えます。","Seuls les administrateurs du canevas peuvent créer des projets."],
  "캔버스 그룹으로 설정": ["设为画布用户组","キャンバスグループに設定","Définir comme groupe du canevas"],
  "캔버스 참가자 직접 추가": ["直接添加画布参与者","キャンバス参加者を直接追加","Ajouter directement des participants au canevas"],
  "설정 패널에서 그룹을 지정하거나 캔버스에 있는 사용자 프로필을 직접 삽입하세요.": ["请在设置面板中指定组，或将画布中的用户资料直接插入。","設定パネルでグループを指定するか、キャンバス上のユーザープロフィールを直接挿入してください。","Spécifiez un groupe dans les paramètres ou insérez directement les profils utilisateur sur le canevas."],
  "캔버스 그룹 지정": ["指定画布用户组","キャンバスグループを指定","Désigner un groupe du canevas"],
  "선택한 그룹 캔버스에 삽입": ["将所选组插入画布","選択したグループをキャンバスに挿入","Insérer le groupe sélectionné sur le canevas"],
  "캔버스 사용자 프로필 직접 삽입": ["直接插入画布用户资料","キャンバスユーザープロフィールを直接挿入","Insérer directement des profils utilisateur sur le canevas"],
  "원하는 프로필을 바로 삽입하거나 여러 명을 선택해 그룹으로 삽입하세요.": ["可直接插入单个用户资料，或选择多人作为用户组插入。","必要なプロフィールをそのまま挿入するか、複数人を選択してグループとして挿入してください。","Insérez un profil directement ou sélectionnez-en plusieurs pour les insérer en groupe."],
  "선택한 프로필 {v0}명 삽입": ["插入所选的 {v0} 个资料","選択した {v0} 名のプロフィールを挿入","Insérer {v0} profil(s) sélectionné(s)"],
  "삽입": ["插入","挿入","Insérer"],
  "내 프로필 삽입": ["插入我的资料","自分のプロフィールを挿入","Insérer mon profil"],
  "이름 · HTML 변수명": ["名称 · HTML 变量名","名前・HTML 変数名","Nom · Nom de variable HTML"],
