  "빠른 테두리 두께": ["快捷边框粗细","クイック枠線の太さ","Épaisseur de bordure rapide"],
  "빠른 투명도": ["快捷不透明度","クイック不透明度","Opacité rapide"],
  "글자 크기 줄이기": ["减小字号","文字サイズを小さく","Réduire la taille de police"],
  "글자 크기 키우기": ["增大字号","文字サイズを大きく","Augmenter la taille de police"],
  "맨 앞으로 가져오기": ["置于顶层","最前面へ移動","Mettre au premier plan"],
  "앞": ["顶层","前面","Avant"],
  "맨 뒤로 보내기": ["置于底层","最背面へ移動","Mettre à l’arrière-plan"],
  "뒤": ["底层","背面","Arrière"],
  "프리셋": ["预设","プリセット","Préréglages"],
  "스타일 복사 (Alt+Ctrl+C)": ["复制样式 (Alt+Ctrl+C)","スタイルをコピー (Alt+Ctrl+C)","Copier le style (Alt+Ctrl+C)"],
  "스타일 붙여넣기 (Alt+Ctrl+V)": ["粘贴样式 (Alt+Ctrl+V)","スタイルを貼り付け (Alt+Ctrl+V)","Coller le style (Alt+Ctrl+V)"],
  "스타일 붙여넣기": ["粘贴样式","スタイルを貼り付け","Coller le style"],
  "붙이기": ["粘贴","貼り付け","Coller"],
