  "4면 개별 두께 · 기준선 · 점선 · 끝 모양": ["四边独立粗细 · 对齐 · 虚线 · 线端样式","4辺の個別太さ・基準線・破線・線端形状","Épaisseur par côté · alignement · tirets · extrémités"],
