  "상하좌우 개별 두께 지정": ["分别设置四边粗细","上下左右の太さを個別に指定","Définir l’épaisseur de chaque côté"],
  "전체 두께 통일": ["统一四边粗细","全体の太さを統一","Unifier l’épaisseur des côtés"],
