  "PNG, JPG, WebP, GIF 등 시각 자료": ["PNG、JPG、WebP、GIF 等视觉素材","PNG、JPG、WebP、GIF などの視覚資料","Ressources visuelles telles que PNG, JPG, WebP et GIF"],
  "음성, 녹음, MP3/WAV/OGG 오디오": ["语音、录音与 MP3/WAV/OGG 音频","音声、録音、MP3/WAV/OGG オーディオ","Voix, enregistrements et audio MP3/WAV/OGG"],
