  "입력 내용과 첨부·연결된 객체의 형식을 자동으로 판별합니다.": ["自动识别输入文本、附件及已连接对象的格式。","入力内容や添付・接続されたオブジェクトの形式を自動で判別します。","Détecte automatiquement le format du texte saisi, des pièces jointes et des objets connectés."],
  "라우팅 AI 에이전트가 입력 의도와 형식을 분석해 적합한 에이전트를 선택합니다.": ["路由 AI 智能体会分析输入意图和格式，以选择最合适的目标智能体。","ルーティング AI エージェントが入力の意図と形式を分析し、適切なエージェントを選択します。","Un routeur IA analyse l’intention et le format d’entrée pour choisir l’agent adapté."],
  "일치 경로 없으면 건너뜀": ["无匹配路由时跳过","一致する経路がない場合はスキップ","Ignorer si aucune route ne correspond"],
  "연결 방향(DAG)에 따라 순차·병렬로 실행합니다.": ["按照连接方向 (DAG) 顺序或并行执行。","接続方向 (DAG) に従って順次および並列で実行します。","Exécute de façon séquentielle et parallèle selon les connexions orientées (DAG)."],
  "핸드오프·피드백·수정 요청을 반복하며 합의에 도달합니다.": ["通过反复交接、反馈与修改请求逐步达成共识。","引き継ぎ・フィードバック・修正依頼を反復しながら合意に至ります。","Itère les passages de relais, retours et révisions jusqu’à parvenir à un consensus."],
  "감독 에이전트가 작업을 분배하고 결과를 검토·종합합니다.": ["由监督智能体分配任务、审阅结果并汇总输出。","監督エージェントが作業を割り当て、結果を確認・統合します。","Un agent superviseur répartit le travail, examine les résultats et synthétise la sortie."],
  "범용 협업자": ["通用协作者","汎用コラボレーター","Collaborateur polyvalent"],
  "기획자 에이전트": ["规划智能体","プランナーエージェント","Agent planificateur"],
  "기획자 · 아키텍트": ["规划者 · 架构师","プランナー・アーキテクト","Planificateur · Architecte"],
  "리서처 에이전트": ["研究智能体","リサーチャーエージェント","Agent chercheur"],
  "구현 에이전트": ["构建智能体","ビルダーエージェント","Agent constructeur"],
  "구현자 · 엔지니어": ["构建者 · 工程师","ビルダー・エンジニア","Constructeur · Ingénieur"],
  "리뷰어 에이전트": ["审查智能体","レビュアーエージェント","Agent réviseur"],
  "품질 검토 · QA": ["质量审查 · QA","品質レビュー・QA","Relecture · QA"],
  "작성가 에이전트": ["撰写智能体","ライターエージェント","Agent rédacteur"],
  "편집 · 종합 작성가": ["编辑 · 综合撰写","編集・統合ライター","Éditeur · Synthétiseur"],
  "입력 객체에서 출발해 기획자·구현자·리뷰어가 최대 2라운드 피드백 루프로 협업하고 출력 객체에 결과를 저장합니다.": ["从输入对象出发，规划者、构建者与审查者通过最多 2 轮反馈循环协同工作，并将结果写入输出对象。","入力オブジェクトから始まり、プランナー・ビルダー・レビュアーが最大 2 ラウンドのフィードバックループで連携し、結果を出力オブジェクトに保存します。","À partir de l’objet d’entrée, le planificateur, le constructeur et le réviseur collaborent sur 2 cycles de retour maximum et écrivent le résultat dans l’objet de sortie."],
  "입력 객체를 받아 두 분석 에이전트가 병렬로 검토한 뒤 종합 에이전트가 출력 객체에 통합합니다.": ["接收输入对象后，两个分析智能体并行审查，随后由综合智能体将结果整合到输出对象中。","入力オブジェクトを受け取り、2 つの分析エージェントが並列で検討した後、統合エージェントが出力オブジェクトにまとめます。","Deux agents analystes examinent l’objet d’entrée en parallèle, puis un agent synthétiseur fusionne leurs résultats dans l’objet de sortie."],
  "입력 객체를 받아 감독 에이전트가 리서처·구현자에게 작업을 위임하고 결과를 출력 객체에 보고합니다.": ["接收输入对象后，监督智能体将任务委派给研究者和构建者，并将结果报告至输出对象。","入力オブジェクトを受け取り、監督エージェントがリサーチャーとビルダーに作業を委任し、結果を出力オブジェクトに報告します。","L’agent superviseur délègue les tâches issues de l’objet d’entrée au chercheur et au constructeur, puis transmet le résultat à l’objet de sortie."],
  "텍스트·이미지·오디오·동영상·PDF 입력을 라우터가 포맷과 지능형 판단으로 전문 에이전트에 분기하고 출력 객체로 모읍니다.": ["路由器根据格式规则和智能判断，将文本、图像、音频、视频与 PDF 输入分发至专业智能体，并汇总到输出对象中。","テキスト・画像・音声・動画・PDF 入力をルーターが形式ルールと知的判断で専門エージェントへ振り分け、出力オブジェクトに集約します。","Le routeur oriente les entrées texte, image, audio, vidéo et PDF vers des agents spécialisés selon le format ou une décision de l’IA, puis rassemble les résultats dans l’objet de sortie."],
