  "영역 조절은 글자 크기를 유지합니다. 높이를 지정하지 않으면 내용에 따라 영역이 늘어납니다.": ["调整区域大小时字号保持不变。若未指定高度，区域将随内容自动扩展。","エリアのサイズを変更しても文字サイズは維持されます。高さを指定しない場合、内容に合わせて領域が広がります。","Le redimensionnement conserve la taille de police. Sans hauteur fixe, la zone s’adapte au contenu."],
  "객체의 텍스트에 적용됩니다. 이미지·PDF 원본과 외부 재생 화면의 글자는 변경하지 않습니다.": ["应用于对象中的文本。不会修改图片、PDF 原件或外部播放器中的文字。","オブジェクト内のテキストに適用されます。画像・PDF の原本や外部プレイヤー内の文字は変更されません。","S’applique au texte de l’objet. Le texte intégré aux images, PDF et lecteurs externes reste inchangé."],
