  "· 새로 그리는 선에 적용됩니다.": ["· 适用于新绘制的线条。","· 新しく描く線に適用されます。","· S’applique aux nouveaux traits."],
  " 형광펜은 기본적으로 반투명합니다.": [" 荧光笔默认呈半透明。"," 蛍光ペンは既定で半透明です。"," Les traits du surligneur sont translucides par défaut."],
