  "빗금 진하기": ["斜线不透明度","ハッチングの濃さ","Opacité des hachures"],
  "빗금 진하기 조절": ["调整斜线不透明度","ハッチングの濃さを調整","Ajuster l’opacité des hachures"],
  "투명도를 높이면 빗금 간격이 넓어집니다. 100%는 채우기 없음입니다. 빗금 진하기를 높이면 선이 더 불투명해집니다.": ["提高透明度会加宽斜线间距，100% 表示无填充；提高斜线不透明度会让线条更明显。","透明度を上げるとハッチングの間隔が広がり、100% で塗りつぶしなしになります。濃さを上げると線がより不透明になります。","Une transparence élevée espace les hachures ; 100 % désactive le remplissage. Augmenter l’opacité des hachures rend les traits plus opaques."],
  "0%는 불투명, 100%는 완전히 투명합니다.": ["0% 表示完全不透明，100% 表示完全透明。","0% が不透明、100% が完全な透明です。","0 % est opaque, 100 % est totalement transparent."],
