  "생성 {v0} · 수정 {v1} · 삭제 {v2}. 저장 요청을 대기열에 넣었습니다.": ["创建 {v0} · 更新 {v1} · 删除 {v2}。保存请求已加入队列。","作成 {v0} · 更新 {v1} · 削除 {v2}。保存リクエストをキューに追加しました。","Création {v0} · Mise à jour {v1} · Suppression {v2}. Demandes d’enregistrement mises en file d’attente."],
