  "크기 제한 없는 캔버스의 픽셀 좌표로 작성합니다. 음수 좌표도 사용할 수 있습니다. 같은 ID는 수정하고 새 ID는 생성합니다.": ["在无限画布上使用像素坐标编写，支持负坐标。相同 ID 将更新对象，新 ID 将创建对象。","無限キャンバスのピクセル座標で記述します。負の座標も使用できます。既存の ID は更新され、新しい ID は作成されます。","Utilisez des coordonnées en pixels sur un canevas infini (coordonnées négatives prises en charge). Les ID existants mettent à jour les objets ; les nouveaux ID les créent."],
