  "replace 모드: 코드에 없는 기존 객체를 삭제합니다.": ["replace 模式：将删除代码中未包含的现有对象。","replace モード: コードに含まれない既存のオブジェクトを削除します。","Mode replace : supprime les objets existants omis dans le code."],
  "+ 생성": ["+ 创建","+ 作成","+ Créer"],
  "~ 수정": ["~ 更新","~ 更新","~ Mettre à jour"],
  "− 삭제": ["− 删除","− 削除","− Supprimer"],
  "merge는 생략한 객체를 유지합니다. remove로 삭제하거나 replace로 전체 상태를 지정하세요.": ["merge 会保留省略的对象。请使用 remove 删除对象，或使用 replace 指定完整状态。","merge は省略されたオブジェクトを保持します。削除するには remove を、全体を指定するには replace を使用してください。","Le mode merge conserve les objets omis. Utilisez remove pour supprimer ou replace pour définir l’état complet."],
  "변경 검토 · Ctrl/⌘+S": ["审阅更改 · Ctrl/⌘+S","変更を確認 · Ctrl/⌘+S","Examiner les modifications · Ctrl/⌘+S"],
  "검토한 변경 적용": ["应用已审阅的更改","確認した変更を適用","Appliquer les modifications examinées"],
