  "테마 기본색으로 복원": ["恢复主题默认颜色","テーマの既定色に戻す","Rétablir la couleur du thème"],
  "이 브라우저에서 캔버스별로 저장됩니다.": ["按画布保存在此浏览器中。","このブラウザーにキャンバスごとに保存されます。","Enregistrée par canevas dans ce navigateur."],
  "그래프 설정": ["图表设置","グラフ設定","Paramètres du graphique"],
