  "데이터 (CSV 또는 탭으로 구분)": ["数据（CSV 或制表符分隔）","データ（CSV またはタブ区切り）","Données (CSV ou séparées par des tabulations)"],
  "그래프 데이터": ["图表数据","グラフデータ","Données du graphique"],
  "첫 행은 열 이름, 첫 열은 항목입니다. 나머지 열에 숫자를 입력하세요.": ["第一行为列名，第一列为标签，其余列请输入数值。","1 行目は列名、1 列目は項目名です。残りの列に数値を入力してください。","La première ligne contient les noms de colonnes et la première colonne contient les libellés. Saisissez des nombres dans les autres colonnes."],
  "원형 그래프는 첫 번째 숫자 열의 양수만 표시합니다.": ["饼图仅显示第一个数值列中的正数。","円グラフは最初の数値列の正の値のみを表示します。","Les graphiques en secteurs n’affichent que les valeurs positives de la première colonne numérique."],
  "산점도는 첫 열을 X 값으로 사용합니다.": ["散点图使用第一列作为 X 值。","散布図は 1 列目を X 値として使用します。","Les nuages de points utilisent la première colonne comme valeurs X."],
  "다른 사용자가 데이터를 변경했습니다. 최신 데이터를 불러온 뒤 다시 편집하세요.": ["其他用户已修改数据。请先加载最新数据后再编辑。","他のユーザーがデータを変更しました。最新データを読み込んでから編集し直してください。","Un autre utilisateur a modifié les données. Chargez les dernières données avant de modifier à nouveau."],
  "데이터 적용": ["应用数据","データを適用","Appliquer les données"],
  "최신 데이터 불러오기": ["加载最新数据","最新データを読み込む","Charger les dernières données"],
  "계열 {count}": ["系列 {count}","系列 {count}","Série {count}"],
  "설정 패널에서 데이터를 입력하세요.": ["请在设置面板中输入数据。","設定パネルでデータを入力してください。","Saisissez les données dans le panneau des paramètres."],
  "객체 클립보드": ["对象剪贴板","オブジェクトクリップボード","Presse-papiers d’objets"],
  "객체 붙여넣기 {count}/{total}": ["正在粘贴对象 {count}/{total}","オブジェクトを貼り付け中 {count}/{total}","Collage des objets {count}/{total}"],
  "객체 {count}개를 붙여넣었습니다.": ["已粘贴 {count} 个对象。","{count} 個のオブジェクトを貼り付けました。","{count} objet(s) collé(s)."],
  "함께 복사되지 않은 연결 대상의 화살표는 제외했습니다.": ["已跳过目标未被一同复制的连接线。","同時にコピーされなかった接続先への矢印は除外されました。","Les connecteurs vers des cibles manquantes ont été ignorés."],
  "멘션할 사용자": ["要提及的用户","メンションするユーザー","Personnes à mentionner"],
  "@로 멘션 · Enter 전송 · Shift + Enter 줄바꿈": ["@ 提及 · Enter 发送 · Shift + Enter 换行","@ でメンション · Enter で送信 · Shift + Enter で改行","@ pour mentionner · Entrée pour envoyer · Maj + Entrée pour un saut de ligne"],
