  "텍스트 파일 이름": ["文本文件名","テキストファイル名","Nom du fichier texte"],
  "같은 내용을 다른 방식으로 표시합니다. Markdown 안에서도 $수식$과 코드 블록을 사용할 수 있어요.": ["以不同格式显示相同内容。在 Markdown 中也可以使用 $公式$ 和代码块。","同じ内容を異なる形式で表示できます。Markdown 内でも $数式$ やコードブロックが使えます。","Affichez le même contenu dans différents formats. Le Markdown prend aussi en charge les $formules$ et les blocs de code."],
  "미리보기": ["预览","プレビュー","Aperçu"],
  "{v0} 직접 수정": ["直接编辑 {v0}","{v0} を直接編集","Modifier {v0} directement"],
