  "글자 색상 창 닫기": ["关闭文字颜色选择器","文字色ピッカーを閉じる","Fermer le sélecteur de couleur du texte"],
  "추천 글자 색상": ["推荐文字颜色","おすすめの文字色","Couleurs de texte suggérées"],
  "{label} 글자 색상": ["{label} 文字颜色","{label} の文字色","Couleur de texte {label}"],
