  "기본색으로 되돌리기": ["恢复默认颜色","既定の色に戻す","Rétablir la couleur par défaut"],
  "두 번 클릭해 내용을 작성하세요": ["双击输入内容","ダブルクリックして内容を入力","Double-cliquez pour saisir du contenu"],
