  "0.2초 단위 최대 30개 FPS 및 CPU 사용률 그래프": ["每 0.2 秒采样一次的 FPS 与 CPU 使用率图表（最多 30 个样本）","0.2 秒間隔・最大 30 サンプルの FPS と CPU 使用率グラフ","Graphique FPS et utilisation CPU toutes les 0,2 s (jusqu’à 30 échantillons)"],
  "평균 {v0} FPS · 최저 {v1} · 최고 CPU {v2}%": ["平均 {v0} FPS · 最低 {v1} · 峰值 CPU {v2}%","平均 {v0} FPS · 最低 {v1} · 最大 CPU {v2}%","Moy. {v0} FPS · Min. {v1} · Pic CPU {v2}%"],
  "0.2초 간격으로 측정 중…": ["每 0.2 秒采样中…","0.2 秒間隔で計測中…","Échantillonnage toutes les 0,2 s…"],
