  "새 작업": ["新建任务","新しいタスク","Nouvelle tâche"],
  "작업 편집 닫기": ["关闭任务编辑器","タスク編集を閉じる","Fermer l’éditeur de tâche"],
  "유형": ["类型","種類","Type"],
