  "승인 필요": ["需要审批","承認が必要","Approbation requise"],
  "상위 작업": ["父级事项","親課題","Ticket parent"],
  "스프린트": ["冲刺","スプリント","Sprint"],
  "백로그": ["待办列表","バックログ","Backlog"],
  "선행 작업": ["前置任务","依存関係","Dépendances"],
  "이 작업과 하위 작업을 삭제할까요?": ["确定要删除此任务及其子任务吗？","このタスクとサブタスクを削除しますか？","Supprimer cette tâche et ses sous-tâches ?"],
  "워크플로 관리": ["管理工作流","ワークフロー管理","Gérer le flux de travail"],
  "승인이 필요한 상태는 관리자가 승인한 뒤 적용됩니다. To Do와 Done은 유지됩니다.": ["需要审批的状态将在管理员批准后生效。To Do 和 Done 将保留。","承認が必要なステータスは管理者の承認後に適用されます。To Do と Done は保持されます。","Les statuts soumis à approbation s’appliquent après validation par un administrateur. To Do et Done sont conservés."],
  "상태 이름": ["状态名称","ステータス名","Nom du statut"],
  "승인": ["批准","承認","Approuver"],
  "상태 위로": ["上移状态","ステータスを上へ","Monter le statut"],
  "새 상태": ["新状态","新しいステータス","Nouveau statut"],
  "상태 추가": ["添加状态","ステータスを追加","Ajouter un statut"],
  "종료일": ["结束日期","終了日","Date de fin"],
  "스프린트 목표": ["冲刺目标","スプリント目標","Objectif du sprint"],
  "시작일이나 마감일을 지정하면 타임라인에 표시됩니다.": ["设置开始日期或截止日期后，任务将显示在时间线上。","開始日または期限日を設定するとタイムラインに表示されます。","Définissez une date de début ou d’échéance pour afficher les tâches sur la chronologie."],
  "프로젝트 보드가 삭제되었거나 접근 권한이 없습니다.": ["项目看板已被删除，或您没有访问权限。","プロジェクトボードが削除されたか、アクセス権限がありません。","Le tableau de projet a été supprimé ou vous n’y avez pas accès."],
  "승인 대기": ["待审批","承認待ち","En attente d’approbation"],
  "삭제된 작업": ["已删除的任务","削除されたタスク","Tâche supprimée"],
  "미할당": ["未分配","未割り当て","Non attribué"],
  "반려": ["拒绝","却下","Rejeter"],
  "프로젝트 이름": ["项目名称","プロジェクト名","Nom du projet"],
  "작업": ["任务","タスク","Tâches"],
  "이슈 생성": ["创建事项","課題を作成","Créer un ticket"],
  "워크플로": ["工作流","ワークフロー","Flux de travail"],
  "프로젝트 보기": ["项目视图","プロジェクトビュー","Vues du projet"],
  "작업 검색": ["搜索任务","タスクを検索","Rechercher des tâches"],
