  "모든 담당자": ["所有负责人","すべての担当者","Tous les responsables"],
  "스프린트 선택": ["选择冲刺","スプリントを選択","Sélectionner un sprint"],
  "스프린트 생성": ["创建冲刺","スプリントを作成","Créer un sprint"],
  "마일스톤 생성": ["创建里程碑","マイルストーンを作成","Créer un jalon"],
  "일정 편집": ["编辑日程","スケジュールを編集","Modifier le calendrier"],
  "스프린트 시작": ["开始冲刺","スプリントを開始","Démarrer le sprint"],
  "스프린트 종료 · 미완료 작업을 백로그로": ["结束冲刺 · 将未完成任务移回待办列表","スプリントを終了 · 未完了タスクをバックログへ戻す","Clôturer le sprint · Renvoyer les tâches inachevées au backlog"],
  "스프린트를 생성하고 작업을 배정해주세요.": ["请创建冲刺并为其分配任务。","スプリントを作成してタスクを割り当ててください。","Créez un sprint et attribuez-y des tâches."],
  "작업 위로": ["上移任务","タスクを上へ","Monter la tâche"],
  "작업 아래로": ["下移任务","タスクを下へ","Descendre la tâche"],
  "작업 상태": ["任务状态","タスクのステータス","Statut de la tâche"],
  "스프린트 성과": ["冲刺表现","スプリント実績","Performance du sprint"],
  "완료율": ["完成率","完了率","Taux d’achèvement"],
  "미완료": ["未完成","未完了","Inachevé"],
  "완료 포인트 · 스프린트별 속도": ["已完成点数 · 各冲刺速率","完了ポイント · スプリント別ベロシティ","Points terminés · Vélocité par sprint"],
  "성과는 열람 권한이 있는 작업을 기준으로 계산됩니다.": ["统计报告仅包含您有权限查看的任务。","レポートは閲覧権限のあるタスクのみを対象に集計されます。","Les rapports incluent uniquement les tâches que vous êtes autorisé à consulter."],
  "이슈를 생성해 프로젝트를 시작하세요.": ["创建一个事项以开始您的项目。","課題を作成してプロジェクトを始めましょう。","Créez un ticket pour démarrer votre projet."],
  "작업 더 보기": ["查看更多任务","タスクをさらに表示","Afficher plus de tâches"],
  "점": [" 分"," 点"," pts"],
  "문제 작업": ["题目操作","問題メニュー","Actions de la question"],
