  "직접 채점": ["手动评分","手動採点","Noter manuellement"],
  "문제 유형": ["题型","問題形式","Type de question"],
  "객관식 · 하나 선택": ["选择题 · 单选","選択式 · 1 つ選択","Choix multiple · une réponse"],
  "주관식": ["主观题","記述式","Réponse libre"],
  "문제 내용": ["题目内容","問題文","Énoncé de la question"],
  "보기": ["选项","選択肢","Choix"],
  "보기 {v0}": ["选项 {v0}","選択肢 {v0}","Choix {v0}"],
