  "보기 추가": ["添加选项","選択肢を追加","Ajouter un choix"],
  "배점": ["满分","配点","Barème maximal"],
  "문제를 수정하면 공동 답안과 채점 결과가 초기화됩니다.": ["修改题目将清除共同答案与评分结果。","問題を編集すると、共同解答と採点結果がリセットされます。","Modifier la question efface la réponse partagée et la note."],
  "문제 저장": ["保存题目","問題を保存","Enregistrer la question"],
  "문제 수정에서 내용을 작성하세요.": ["请在“编辑题目”中填写题目内容。","「問題を編集」から問題文を作成してください。","Utilisez « Modifier la question » pour rédiger l’énoncé."],
  "제출된 공동 답안": ["已提交的共同答案","提出された共同解答","Réponse partagée envoyée"],
