  "드래그해서 폴더 이동": ["拖动以在文件夹之间移动","ドラッグしてフォルダー間を移動","Glisser pour déplacer entre les dossiers"],
  "그룹 이름": ["组名称","グループ名","Nom du groupe"],
  "명": [" 人"," 人"," personne(s)"],
  "추가할 사용자 닉네임과 태그": ["要添加的用户昵称与标签","追加するユーザーのニックネームとタグ","Pseudonyme et tag à ajouter"],
  "찾는 중…": ["正在搜索…","検索中…","Recherche…"],
  "내 프로필 추가": ["添加我的个人资料","自分のプロフィールを追加","Ajouter mon profil"],
  "{v0} 그룹에서 제거": ["从组中移除 {v0}","グループから {v0} を削除","Retirer {v0} du groupe"],
  "테두리": ["边框","枠線","Bordure"],
  "{v0} 테두리 색상": ["{v0} 边框颜色","{v0} の枠線の色","Couleur de bordure de {v0}"],
  "{v0} 닉네임 색상": ["{v0} 昵称颜色","{v0} のニックネームの色","Couleur du pseudonyme de {v0}"],
  "프로필을 모아 보여주는 객체입니다. 캔버스의 접속 권한은 변경하지 않습니다.": ["用于集中展示个人资料的对象，不会更改画布的访问权限。","プロフィールをまとめて表示するオブジェクトです。キャンバスのアクセス権限は変更しません。","Affiche un groupe de profils sans modifier les droits d’accès au canevas."],
  "{v0} 프로필": ["{v0} 个人资料","{v0} のプロフィール","Profil de {v0}"],
  "값과 범위 설정을 확인해주세요.": ["请检查值和范围设置。","値と範囲の設定を確認してください。","Vérifiez les paramètres de valeur et de plage."],
  "값 객체 설정": ["值对象设置","値オブジェクト設定","Paramètres de l’objet valeur"],
  "선택 항목 · 한 줄에 하나": ["选项 · 每行一个","選択肢 · 1 行に 1 つ","Options · une par ligne"],
  "실수 슬라이더": ["实数滑块","実数スライダー","Curseur de nombres réels"],
  "값 감소": ["减小值","値を減らす","Diminuer la valeur"],
  "값 증가": ["增大值","値を増やす","Augmenter la valeur"],
