  "공동 값": ["共享值","共有値","Valeur partagée"],
  "참가자": ["参与者","参加者","Participants"],
  "통화 나가기": ["离开通话","通話から退出","Quitter l’appel"],
  "연결 다시 시도": ["重试连接","再接続を試行","Réessayer la connexion"],
  "소리 재생": ["播放音频","音声を再生","Lire l’audio"],
  "나": ["我","自分","Moi"],
  "공유 화면 보기": ["观看共享屏幕","共有画面を見る","Voir l’écran partagé"],
  "{name} 볼륨": ["{name} 的音量","{name} の音量","Volume de {name}"],
  "같은 통화 채널의 참여자와 대화할 수 있어요.": ["可与同一通话频道的参与者对话。","同じ通話チャンネルの参加者と会話できます。","Discutez avec les personnes présentes dans le même canal d’appel."],
  "공유 화면": ["共享屏幕","共有画面","Écran partagé"],
  "공유 화면 닫기": ["关闭共享屏幕","共有画面を閉じる","Fermer l’écran partagé"],
  "화면 연결 중…": ["正在连接屏幕…","画面に接続中…","Connexion à l’écran…"],
  "통화 조작": ["通话控制","通話コントロール","Contrôles d’appel"],
  "삭제 중…": ["正在删除…","削除中…","Suppression…"],
  "화살표 모양": ["箭头样式","矢印のスタイル","Style de flèche"],
  "ERD 관계": ["ERD 关系","ERD リレーション","Relations ERD"],
  "화살표 머리 모양": ["箭头端点样式","矢印の先端スタイル","Pointes de flèche"],
  "시작 머리": ["起点箭头","始点の先端","Pointe de début"],
  "시작 화살표 머리 모양": ["起点箭头样式","始点の矢印スタイル","Pointe de flèche de début"],
  "끝 머리": ["终点箭头","終点の先端","Pointe de fin"],
  "끝 화살표 머리 모양": ["终点箭头样式","終点の矢印スタイル","Pointe de flèche de fin"],
  "ERD 관계는 시작과 끝에서 각각 선택합니다. 각 끝은 반대편 객체 하나에 연결될 수 있는 개수를 나타냅니다.": ["分别为起点和终点选择关系。每一端表示可连接到对侧单个对象的数量。","始点と終点でそれぞれ関係を選択します。各端は反対側の 1 つのオブジェクトに接続できる数を示します。","Choisissez une relation à chaque extrémité. Chaque bout indique combien d’instances peuvent être liées à une instance opposée."],
  "머리 크기": ["箭头大小","先端のサイズ","Taille des pointes"],
  "확인 중…": ["正在验证…","確認中…","Vérification…"],
  "격리 VM 실행": ["隔离 VM 运行","分離 VM 実行","Exécution en VM isolée"],
  "예: claude -p --permission-mode bypassPermissions": ["例如：claude -p --permission-mode bypassPermissions","例: claude -p --permission-mode bypassPermissions","Ex. : claude -p --permission-mode bypassPermissions"],
  "설치됨": ["已安装","インストール済み","Installé"],
  "미설치": ["未安装","未インストール","Non installé"],
  "상태 확인 전": ["尚未检查","未確認","Pas encore vérifié"],
  "개인 API 키 사용": ["使用个人 API 密钥","個人 API キーを使用中","Clé API personnelle utilisée"],
  "설치 중…": ["正在安装…","インストール中…","Installation…"],
  "업데이트": ["更新","アップデート","Mettre à jour"],
  "VM에 설치": ["安装到 VM","VM にインストール","Installer dans la VM"],
  "제거": ["卸载","削除","Supprimer"],
  "캔버스 브릿지": ["画布桥接","キャンバスブリッジ","Passerelle du canevas"],
  "입력한 셸 명령은 VM /workspace에서 실행되며 stdin으로 프롬프트, agora-canvas로 캔버스 도구를 전달받습니다.": ["输入的 Shell 命令会在 VM /workspace 中运行，通过 stdin 接收提示词，并通过 agora-canvas 获取画布工具。","入力したシェルコマンドは VM の /workspace で実行され、stdin でプロンプトを、agora-canvas 経由でキャンバスツールを受け取ります。","La commande shell s’exécute dans /workspace de la VM ; elle reçoit la consigne sur stdin et les outils du canevas via agora-canvas."],
  "에이전트 설정에서 {env} 키를 입력하거나 캔버스 터미널에서 로그인하세요.": ["请在智能体设置中输入您的 {env} 密钥，或通过画布终端登录。","エージェント設定で {env} キーを入力するか、キャンバスターミナルからログインしてください。","Saisissez votre clé {env} dans les paramètres de l’agent ou connectez-vous via un Terminal du canevas."],
  "에이전트 실행 방식": ["智能体执行方式","エージェントの実行方式","Mode d’exécution de l’agent"],
  "{tool} API 키 (선택)": ["{tool} API 密钥（可选）","{tool} API キー（任意）","Clé API {tool} (facultatif)"],
  "키 지우기": ["清除密钥","キーを消去","Effacer la clé"],
  "{tool}에게 캔버스 작업을 요청해보세요…": ["请 {tool} 在画布上协助处理任务…","{tool} にキャンバス上の作業を依頼してみましょう…","Demandez à {tool} d’intervenir sur votre canevas…"],
  "바깥 모서리를 드래그해 회전": ["拖动外角进行旋转","外側の角をドラッグして回転","Faites glisser les coins extérieurs pour pivoter"],
  "두 번 클릭해 컬럼 이름 편집": ["双击编辑列名称","ダブルクリックして列名を編集","Double-cliquez pour modifier le nom de la colonne"],
  "컬럼 {v0} 이름": ["列 {v0} 名称","列 {v0} の名前","Nom de la colonne {v0}"],
  "컬럼 이름": ["列名称","列名","Nom de la colonne"],
  "두 번 클릭해 Markdown 셀 편집": ["双击编辑 Markdown 单元格","ダブルクリックして Markdown セルを編集","Double-cliquez pour modifier la cellule Markdown"],
  "{v0}행 {v1}열": ["第 {v0} 行第 {v1} 列","{v0} 行目 {v1} 列目","Ligne {v0}, colonne {v1}"],
