  "클릭하여 원본 페이지 열기": ["点击打开原页面","クリックして元のページを開く","Cliquer pour ouvrir la page d’origine"],
  "유튜브 동영상 미리보기": ["YouTube 视频预览","YouTube 動画プレビュー","Aperçu de la vidéo YouTube"],
  "수식: {v0}": ["公式：{v0}","数式：{v0}","Équation : {v0}"],
  "{v0}에서 크기 조절": ["从{v0}调整大小","{v0}からサイズ変更","Redimensionner depuis : {v0}"],
  "동영상 또는 링크 공유": ["分享视频或链接","動画またはリンクを共有","Partager une vidéo ou un lien"],
  "캔버스 위치에 자료를 추가합니다.": ["在画布的指定位置添加媒体内容。","キャンバスの位置にメディアを追加します。","Ajoutez un média à un emplacement du canevas."],
  "주소": ["网址","URL","URL"],
  "https://youtu.be/... 또는 example.com": ["https://youtu.be/... 或 example.com","https://youtu.be/... または example.com","https://youtu.be/... ou example.com"],
