  "캔버스에 입장하려면 비밀번호를 입력해 주세요.": ["请输入密码以加入此画布。","このキャンバスに参加するにはパスワードを入力してください。","Saisissez le mot de passe pour rejoindre ce canevas."],
  "캔버스 비밀번호 입력": ["输入画布密码","キャンバスのパスワードを入力","Saisir le mot de passe du canevas"],
