  "미분류": ["未分类","未分類","Non classé"],
  "접속 허용 그룹": ["允许访问的组","アクセス許可グループ","Groupes autorisés"],
  "전체 선택": ["全选","すべて選択","Tout sélectionner"],
  "최소 하나 이상의 쓰기 가능 그룹이 필요합니다.": ["至少需要一个具有写入权限的组。","少なくとも 1 つの書き込み可能なグループが必要です。","Au moins un groupe disposant du droit d’écriture est requis."],
  "통화 채널": ["通话频道","通話チャンネル","Canaux d’appel"],
  "채널 이름": ["频道名称","チャンネル名","Nom du canal"],
  "제한된 그룹 채널": ["受限组频道","制限付きグループチャンネル","Canal de groupe restreint"],
  "읽지 않은 메시지": ["未读消息","未読メッセージ","Messages non lus"],
