  "이 카테고리에 채널 추가": ["在此分类下添加频道","このカテゴリーにチャンネルを追加","Ajouter un canal à cette catégorie"],
  "카테고리 이름 변경": ["重命名分类","カテゴリー名を変更","Renommer la catégorie"],
  "카테고리 삭제": ["删除分类","カテゴリーを削除","Supprimer la catégorie"],
