  "이미지를 불러오지 못했습니다.": ["无法加载图片。","画像を読み込めませんでした。","Impossible de charger l’image."],
  "이미지 불러오는 중…": ["正在加载图片…","画像を読み込み中…","Chargement de l’image…"],
  "채팅 이미지": ["聊天图片","チャット画像","Image de discussion"],
  "이미지 확대": ["放大图片","画像を拡大","Agrandir l’image"],
  "클릭하여 원본 크기로 보기": ["点击查看原图尺寸","クリックして元のサイズで表示","Cliquez pour afficher en taille réelle"],
  "동영상을 불러오지 못했습니다.": ["无法加载视频。","動画を読み込めませんでした。","Impossible de charger la vidéo."],
  "동영상 불러오는 중…": ["正在加载视频…","動画を読み込み中…","Chargement de la vidéo…"],
