  "연결 화살표 곡률 조절점 {v0}": ["连接箭头曲率控制点 {v0}","接続矢印の曲率制御点 {v0}","Point de contrôle de courbure {v0} de la flèche de connexion"],
  "{v0}행 × {v1}열 · {v2}": ["{v0} 行 × {v1} 列 · {v2}","{v0} 行 × {v1} 列 · {v2}","{v0} lignes × {v1} colonnes · {v2}"],
