  "협업 라운드": ["协作轮次","協調ラウンド","Tours de collaboration"],
  "감독자 위임": ["监督者委派","監督者による委任","Délégation par superviseur"],
  "자동 추론": ["自动推断","自動推論","Inférence automatique"],
  "사용자 입력": ["用户输入","ユーザー入力","Entrée utilisateur"],
  "라우팅 경로": ["路由路径","ルーティング経路","Voie de routage"],
