  "먹색": ["炭黑","チャコール","Anthracite"],
  "회색": ["灰色","グレー","Gris"],
  "흰색": ["白色","ホワイト","Blanc"],
  "보라색": ["紫色","パープル","Violet"],
  "파란색": ["蓝色","ブルー","Bleu"],
  "청록색": ["青绿色","ティール","Sarcelle"],
